{"path": "/tmp/sv-4c7b863e8751439daceadecda6c20654/Components/Chat/ChannelItem.razor", "file_text": "<div class="channel-item @(IsActive ? "active" : "")" @onclick="OnClick">
    <div class="channel-top">
        <span class="channel-name"># @Channel.Name</span>
        @if (Channel.UnreadCount > 0)
        {
            <span class="unread-badge">@Channel.UnreadCount</span>
