{"path": "/tmp/sv-4c7b863e8751439daceadecda6c20654/Components/Chat/MessageInput.razor", "file_text": "<div class="message-input-area">
    <textarea @bind="_text" @bind:event="oninput"
              placeholder="@Placeholder"
              @onkeydown="HandleKeyDown"
              rows="2"></textarea>
    <button class="send-btn" @onclick="Submit" disabled="@string.IsNullOrWhiteSpace(_text)">
        @ButtonText
    </button>
</div>

@code {
    [Parameter] public string Placeholder { get; set; } = "Type a message…";
    [Parameter] public string ButtonText { get; set; } = "Send";
    [Parameter] public EventCallback<string> OnSubmit { get; set; }

    private string _text = "";

    private async Task HandleKeyDown(KeyboardEventArgs e)
    {
        if (e is { Key: "Enter", ShiftKey: false } && !string.IsNullOrWhiteSpace(_text))
        {
            await Submit();
        }
    }

    private async Task Submit()
    {
        if (string.IsNullOrWhiteSpace(_text)) return;
        var content = _text.Trim();
        _text = "";
        await OnSubmit.InvokeAsync(content);
    }
}
"}

{"path": "/tmp/sv-4c7b863e8751439daceadecda6c20654/Components/Chat/MessageInput.razor.css", "file_text": ".message-input-area {
    display: flex;
    gap: 8px;
    padding: 12px 20px;
    border-top: 1px solid #e0e0e0;
    background: #fff;
    align-items: flex-end;
}

.message-input-area textarea {
    flex: 1;
    resize: none;
    border: 1px solid #ccc;
    border-radius: 8px;
    padding: 10px 12px;
    font-family: inherit;
    font-size: 0.9rem;
    line-height: 1.4;
    outline: none;
    transition: border-color 0.15s;
}

.message-input-area textarea:focus {
    border-color: #1264a3;
}

.send-btn {
    background-color: #007a5a;
    color: #fff;
    border: none;
    border-radius: 8px;
    padding: 10px 20px;
    font-weight: 600;
    font-size: 0.9rem;
    cursor: pointer;
    white-space: nowrap;
    transition: background-color 0.15s;
}

.send-btn:hover:not(:disabled) {
    background-color: #005e47;
}

.send-btn:disabled {
    opacity: 0.5;
    cursor: not-allowed;
}
"}

