            {
                <MessageBubble Message="msg"
                               OnReact="(emoji) => OnReact.InvokeAsync((msg.Id, emoji))" />
            }
        </div>

        <MessageInput Placeholder="Reply…" ButtonText="Reply" OnSubmit="OnSendReply" />
    }
</div>

