.thread-panel {
    display: flex;
    flex-direction: column;
    height: 100%;
    background-color: #fff;
    border-left: 1px solid #e0e0e0;
}

.thread-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 12px 16px;
    border-bottom: 1px solid #e0e0e0;
    flex-shrink: 0;
}

.thread-header h4 {
    margin: 0;
    font-size: 1.05rem;
    font-weight: 700;
    color: #1d1c1d;
}

.close-btn {
    background: none;
    border: none;
    font-size: 1.1rem;
    cursor: pointer;
    color: #616061;
    padding: 4px 8px;
    border-radius: 4px;
    line-height: 1;
}

.close-btn:hover {
    background-color: #f0f0f0;
    color: #1d1c1d;
}

.thread-root {
    border-bottom: 1px solid #e8e8e8;
    background-color: #fafafa;
}

.thread-divider {
    display: flex;
    align-items: center;
    padding: 8px 20px;
    font-size: 0.78rem;
    font-weight: 600;
    color: #616061;
}

.thread-divider::after {
    content: "";
    flex: 1;
    margin-left: 10px;
    border-bottom: 1px solid #e0e0e0;
}

.thread-messages {
    flex: 1;
    overflow-y: auto;
    padding: 4px 0;
}

