@page "/chat"
@using sv_4c7b863e8751439daceadecda6c20654.Services
@rendermode InteractiveServer
@inject IChatService ChatService

<PageTitle>Chat</PageTitle>

<div class="chat-layout">
    <div class="sidebar-col">
        <ChannelSidebar Channels="_channels"
                        ActiveChannelId="@(_selectedChannel?.Id ?? 0)"
                        OnChannelSelected="SelectChannel" />
    </div>

    <div class="main-col">
        @if (_selectedChannel is not null)
        {
            <MessageArea ChannelName="@_selectedChannel.Name"
                         ChannelDescription="@_selectedChannel.Description"
                         Messages="_messages"
                         ReplyCounts="_replyCounts"
                         HasMoreMessages="_hasMoreMessages"
                         IsLoadingMore="_isLoadingMore"
                         OnLoadMore="LoadOlderMessages"
                         OnOpenThread="OpenThread"
                         OnReact="HandleReaction"
                         OnSendMessage="SendMessage" />
        }
    </div>

    @if (_threadRootMessage is not null)
    {
        <div class="thread-col">
            <ThreadPanel RootMessage="_threadRootMessage"
                         ThreadMessages="_threadMessages"
                         OnClose="CloseThread"
                         OnSendReply="SendThreadReply"
                         OnReact="HandleReaction" />
        </div>
    }
</div>

@code {
    private const int PageSize = 30;

    private List<Channel> _channels = [];
    private Channel? _selectedChannel;
    private List<Message> _messages = [];
    private Dictionary<int, int> _replyCounts = [];
    private bool _hasMoreMessages = true;
    private bool _isLoadingMore;

    private Message? _threadRootMessage;
    private List<Message> _threadMessages = [];

    protected override async Task OnInitializedAsync()
    {
        _channels = await ChatService.GetChannelsAsync();
        if (_channels.Count > 0)
        {
            await SelectChannel(_channels[0]);
        }
    }

    private async Task SelectChannel(Channel channel)
    {
        _selectedChannel = channel;
        _messages = [];
        _replyCounts = [];
        _hasMoreMessages = true;
        _threadRootMessage = null;
        _threadMessages = [];

        var messages = await ChatService.GetMessagesAsync(channel.Id, 0, PageSize);
        _messages = messages;
        _hasMoreMessages = messages.Count >= PageSize;
        ComputeReplyCounts();

        await ChatService.MarkChannelReadAsync(channel.Id);
        UpdateChannelUnread(channel.Id);
    }

    private async Task LoadOlderMessages()
    {
        if (_selectedChannel is null || _isLoadingMore) return;
        _isLoadingMore = true;

        var older = await ChatService.GetMessagesAsync(_selectedChannel.Id, _messages.Count, PageSize);
        _messages.InsertRange(0, older);
        _hasMoreMessages = older.Count >= PageSize;
        ComputeReplyCounts();

        _isLoadingMore = false;
    }

    private async Task SendMessage(string content)
    {
        if (_selectedChannel is null) return;
        var msg = await ChatService.SendMessageAsync(_selectedChannel.Id, content, null);
        _messages.Add(msg);
    }

    private async Task OpenThread(int messageId)
    {
        _threadRootMessage = _messages.FirstOrDefault(m => m.Id == messageId);
        if (_threadRootMessage is null) return;

        _threadMessages = await ChatService.GetThreadAsync(messageId);
        if (_replyCounts.ContainsKey(messageId))
        {
            _replyCounts[messageId] = _threadMessages.Count;
        }
        else
        {
            _replyCounts[messageId] = _threadMessages.Count;
        }
    }

    private void CloseThread()
    {
        _threadRootMessage = null;
        _threadMessages = [];
    }

    private async Task SendThreadReply(string content)
    {
        if (_selectedChannel is null || _threadRootMessage is null) return;
        var reply = await ChatService.SendMessageAsync(_selectedChannel.Id, content, _threadRootMessage.Id);
        _threadMessages.Add(reply);
        _replyCounts[_threadRootMessage.Id] = _threadMessages.Count;
    }

    private async Task HandleReaction((int MessageId, string Emoji) args)
    {
        await ChatService.AddReactionAsync(args.MessageId, args.Emoji);
        await RefreshMessage(args.MessageId);
    }

    private async Task RefreshMessage(int messageId)
    {
        // Refresh by reloading the thread or finding the message in the main list
        if (_threadRootMessage is not null)
        {
            _threadMessages = await ChatService.GetThreadAsync(_threadRootMessage.Id);
        }

        if (_selectedChannel is null) return;

        // Find the message index and try to update from a fresh load
        var idx = _messages.FindIndex(m => m.Id == messageId);
        if (idx >= 0)
        {
            var fresh = await ChatService.GetMessagesAsync(_selectedChannel.Id, idx, 1);
            if (fresh.Count > 0)
            {
                _messages[idx] = fresh[0];
            }
        }
    }

    private void ComputeReplyCounts()
    {
        _replyCounts.Clear();
        foreach (var msg in _messages)
        {
            if (msg.ReplyToId is { } rootId)
            {
                _replyCounts.TryGetValue(rootId, out var count);
                _replyCounts[rootId] = count + 1;
            }
        }
    }

    private void UpdateChannelUnread(int channelId)
    {
        var idx = _channels.FindIndex(c => c.Id == channelId);
        if (idx >= 0)
        {
            var ch = _channels[idx];
            _channels[idx] = ch with { UnreadCount = 0 };
        }
    }
}

